INSERT INTO `behavioural_types` (`id`, `code`, `name`, `instructions`, `order_index`) VALUES (1, 'A', 'Natural-Motivator', 'Please choose the statement that you find most appropriate. In case you find both true of you choose the statement that connects with you most strongly. In case you feel neither is true of you, choose the one which is more likely to be true of you. ', 0);
INSERT INTO `behavioural_types` (`id`, `code`, `name`, `instructions`, `order_index`) VALUES (2, 'B', 'Conditioned', 'On the following pages are several pairs of statements describing possible behavioral responses. For each pair, please choose one statement that is most likely to be true of you. ', 1);
